def carry_over_data(apps, schema_editor):
    """Move old single-table data into the new structure without losing anything."""
    from django.utils import timezone

    UserProfile = apps.get_model("properties", "UserProfile")
    ProviderApplication = apps.get_model("properties", "ProviderApplication")
    ProviderProfile = apps.get_model("properties", "ProviderProfile")
    BoardingHouse = apps.get_model("properties", "BoardingHouse")
    BoardingRoom = apps.get_model("properties", "BoardingRoom")
    BoardingTenancy = apps.get_model("properties", "BoardingTenancy")
    Booking = apps.get_model("properties", "Booking")
    Commission = apps.get_model("properties", "Commission")
    CommissionRate = apps.get_model("properties", "CommissionRate")

    # 1. Old provider role -> provider application (and profile if already verified).
    status_map = {"verified": "approved", "rejected": "rejected"}
    for profile in UserProfile.objects.filter(role="provider").select_related("user"):
        status = status_map.get(profile.verification_status, "pending")
        application = ProviderApplication.objects.create(
            user=profile.user,
            provider_type="landlord",
            business_name=profile.business_name or profile.user.username,
            phone_number=profile.phone_number or "",
            status=status,
            reviewed_at=timezone.now() if status != "pending" else None,
        )
        if status == "approved":
            ProviderProfile.objects.create(
                user=profile.user,
                application=application,
                provider_type="landlord",
                business_name=application.business_name,
                phone_number=application.phone_number,
            )
            profile.active_mode = "provider"
            profile.save(update_fields=["active_mode"])

    # 2. A boarding house's single bed count becomes one room with that capacity.
    for house in BoardingHouse.objects.all():
        room = BoardingRoom.objects.create(
            boarding_house=house,
            name="Room 1",
            room_type="dorm" if house.capacity >= 4 else "single" if house.capacity == 1 else "double",
            capacity=max(house.capacity, 1),
            price_per_bed=house.rent_per_bed,
        )
        house.is_approved = True
        house.save(update_fields=["is_approved"])
        for tenancy in BoardingTenancy.objects.filter(boarding_house=house):
            tenancy.room = room
            tenancy.check_in_date = tenancy.move_in_date
            tenancy.check_out_date = tenancy.move_out_date
            tenancy.occupant_name = tenancy.student.username if tenancy.student_id else "Occupant"
            if tenancy.status in ("requested", "rejected"):
                tenancy.status = "cancelled"
            tenancy.save()

    # 3. Old booking statuses and money split.
    for booking in Booking.objects.select_related("listing"):
        booking.status = {"requested": "pending"}.get(booking.status, booking.status)
        booking.category = booking.listing.kind if booking.listing.kind in ("stay", "rent") else "stay"
        booking.periods = max((booking.check_out - booking.check_in).days, 1)
        booking.unit_price = booking.listing.price
        booking.save()
    for commission in Commission.objects.select_related("booking"):
        commission.gross_amount = commission.booking.total_amount
        commission.provider_net = commission.booking.total_amount - commission.amount
        commission.status = {"payable": "earned", "paid": "paid_out"}.get(commission.status, commission.status)
        commission.save()

    # 4. Default commission: 10% for every category, editable by the administrator.
    for category in ("stay", "rent", "boarding"):
        CommissionRate.objects.get_or_create(category=category)


